    import random
    import time

    LANGUAGE_WRAPPER = 'In a round‐robin tournament with {team_count} teams labeled 1 through {team_count}, each unordered pair of distinct teams plays exactly {rounds_per_pair} independent games. Team i has a positive strength s_i, and the ordered list of strengths is {strengths} (so s_1, s_2, …, s_{team_count} are given in that order). In any single game between teams i and j, the probability that i wins is s_i/(s_i + s_j); there are no ties, and all games are mutually independent. Let the probability that the tournament produces neither a team that wins all its games nor a team that loses all its games be equal to m/d in lowest terms. Find m + d.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Try multiple times to ensure difficulty constraints are met
for _ in range(100):
    team_count = rng.randint(6, 8)  # ensure non-trivial, larger than seed
    rounds_per_pair = rng.randint(2, 4)  # at least double round-robin
    strengths = [rng.randint(2, 9) for _ in range(team_count)]
    # enforce difficulty: at least 3 distinct strengths
    if len(set(strengths)) < 3:
        continue
    return {'team_count': team_count, 'rounds_per_pair': rounds_per_pair, 'strengths': strengths}
# Fallback (should rarely happen)
return {'team_count': 6, 'rounds_per_pair': 2, 'strengths': [2, 3, 4, 5, 6, 7]}

    def verifier(assign):
# Validate presence and types
try:
    n = int(assign['team_count'])
    r = int(assign['rounds_per_pair'])
    strengths = list(assign['strengths'])
except Exception:
    # invalid structure
    return (False, None)

# Domain constraints enforcing non-triviality and feasibility
if not isinstance(n, int) or not isinstance(r, int):
    return (False, None)
if n < 6:
    # Too small; trivializes symmetry
    return (False, None)
if r < 2:
    # Must be at least double round-robin to boost difficulty
    return (False, None)
if not isinstance(strengths, list) or len(strengths) != n:
    return (False, None)
if any((not isinstance(x, int) or x <= 0) for x in strengths):
    return (False, None)
if len(set(strengths)) < 3:
    # Prevent nearly uniform easy cases
    return (False, None)

from fractions import Fraction

S = strengths
# Precompute single-game win probabilities p[i][j] = s_i / (s_i + s_j) for i != j
p = [[None for _ in range(n)] for _ in range(n)]
for i in range(n):
    for j in range(n):
        if i == j:
            p[i][j] = None
        else:
            denom = S[i] + S[j]
            # denom > 0 by constraints
            p[i][j] = Fraction(S[i], denom)

def pow_fraction(fr, k):
    # Fraction exponentiation by small integer k
    res = Fraction(1, 1)
    for _ in range(k):
        res *= fr
    return res

# A_i: probability team i is undefeated (wins all r games vs every other team)
A = []
for i in range(n):
    prod = Fraction(1, 1)
    for j in range(n):
        if j == i:
            continue
        prod *= pow_fraction(p[i][j], r)
    A.append(prod)

# B_i: probability team i is winless (loses all r games vs every other team)
B = []
for i in range(n):
    prod = Fraction(1, 1)
    for j in range(n):
        if j == i:
            continue
        # probability j beats i in a single game
        prod *= pow_fraction(Fraction(S[j], S[i] + S[j]), r)
    B.append(prod)

# C_{ij}: probability (i undefeated) AND (j winless), for i != j
total_C = Fraction(0, 1)
for i in range(n):
    for j in range(n):
        if i == j:
            continue
        prod = Fraction(1, 1)
        # r games between i and j: i must win all
        prod *= pow_fraction(Fraction(S[i], S[i] + S[j]), r)
        # For each k != i, j: i must win all r vs k
        for k in range(n):
            if k == i or k == j:
                continue
            prod *= pow_fraction(Fraction(S[i], S[i] + S[k]), r)
        # For each k != i, j: j must lose all r vs k (i.e., k wins all r over j)
        for k in range(n):
            if k == i or k == j:
                continue
            prod *= pow_fraction(Fraction(S[k], S[k] + S[j]), r)
        total_C += prod

P = Fraction(1, 1) - sum(A, Fraction(0, 1)) - sum(B, Fraction(0, 1)) + total_C

# Sanity bounds
if P < 0 or P > 1:
    # Numerical or logical inconsistency; reject
    return (False, None)

answer = P.numerator + P.denominator
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

